{"command":"cat > /workspace/tools/parse_help.py <<'EOF'
#!/usr/bin/env python3
"""Parse captured help text to extract option tables."""
import re, sys, os, json

def parse_options(text):
    lines = text.split('\n')
    # find OPTIONS section
    try:
        start = lines.index('OPTIONS')
    except ValueError:
        return []
    opts = []
    section = None
    i = start + 1
    cur = None
    while i < len(lines):
        l = lines[i]
        if l and not l.startswith(' '):
            # new top-level section (e.g. KNOWN ISSUES)
            if l.startswith('Options to specify'):
                pass
            else:
                break
        if l.startswith('Options to specify input/output files:'):
            section = 'inout'
        elif l.startswith('Options to specify input files:'):
            section = 'in'
        elif l.startswith('Options to specify output files:'):
            section = 'out'
        elif l.startswith('Other options:'):
            section = 'other'
        elif l.startswith(' -'):
            m = re.match(r'^ -(\[no\])?([A-Za-z0-9_]+)\s*(.*)$', l)
            assert m, l
            isbool = m.group(1) is not None
            name = m.group(2)
            rest = m.group(3)
            cur = {'name': name, 'section': section, 'bool': isbool, 'desc': ''}
            # type
            tm = re.match(r'^(\[<[^>]*>( \[\.\.\.\])?\]|<[^>]*>)?\s*(.*)$', rest)
            typ = tm.group(1) or ''
            rest2 = tm.group(3)
            flags = re.findall(r'\(([^()]*)\)', rest2)
            # default is the first paren group unless it's Opt./Lib.
            default = None
            fl = []
            for f in flags:
                if f in ('Opt.', 'Lib.', 'Opt., Lib.'):
                    fl += [x.strip() for x in f.split(',')]
                else:
                    default = f
            cur['type'] = typ
            cur['default'] = default
            cur['flags'] = fl
            opts.append(cur)
        elif l.startswith('           ') and cur is not None:
            cur['desc'] += (' ' if cur['desc'] else '') + l.strip()
        i += 1
    return opts

if __name__ == '__main__':
    d = sys.argv[1]
    allopts = {}
    for fn in sorted(os.listdir(d)):
        cmd = fn[:-4]
        text = open(os.path.join(d, fn)).read()
        allopts[cmd] = parse_options(text)
    json.dump(allopts, sys.stdout, indent=1)
EOF
