// Core declarations for the gmx command-line reimplementation.
#pragma once
#include <cstdio>
#include <string>
#include <vector>
#include <map>
#include <stdexcept>
#include "data.h"

namespace gmx {

extern const char* const kVersionString;   // e.g. "2027.0-dev-..."
extern const char* const kDataPrefix;

// ---------------------------------------------------------------- context
struct ProgramContext {
    std::string programName;   // basename of argv[0]
    std::string fullPath;      // resolved path of the binary
    std::string workingDir;    // current working directory
    std::string commandLine;   // formatted command line
    std::string displayName;   // "gmx <module>" or programName
};
extern ProgramContext g_context;
void initContext(int argc, char** argv);

// ---------------------------------------------------------------- errors
struct GmxError : public std::exception {
    std::string title;      // e.g. "Error in user input"
    std::string sourceFile; // e.g. "src/gromacs/commandline/cmdlineparser.cpp"
    int         line;
    std::string function;   // optional
    std::string message;    // possibly multi-line, pre-indented
    int         exitCode;
    GmxError(std::string t, std::string sf, int ln, std::string fn, std::string msg, int code = 1)
        : title(std::move(t)), sourceFile(std::move(sf)), line(ln), function(std::move(fn)),
          message(std::move(msg)), exitCode(code) {}
    const char* what() const noexcept override { return message.c_str(); }
};

// Convenience constructors mimicking common GROMACS error sites.
GmxError userInputError(const std::string& msg, const std::string& file, int line, const std::string& func);
GmxError fatalError(const std::string& msg, const std::string& file, int line);
GmxError fileIOError(const std::string& msg, const std::string& file, int line);
GmxError libraryFileNotFound(const std::string& fileName);  // residuetypes.dat etc.

void printError(FILE* fp, const GmxError& e);

// ---------------------------------------------------------------- output
std::string wrapText(const std::string& text, int width = 78, int indent = 0);
std::string formatString(const char* fmt, ...);
void printHeader(FILE* fp, bool copyright);
void printFooter(FILE* fp);
std::string chooseQuote();
std::string chooseAcronym();
std::string xvgHeaderComments(const std::string& moduleName); // "# This file was created ... "

// ---------------------------------------------------------------- settings
struct CommonSettings {
    bool quiet = false;
    bool help = false;
    bool version = false;
    bool copyright = false;
    int  nice = 19;
    bool backup = true;
};
extern CommonSettings g_settings;

// ---------------------------------------------------------------- options
struct OptionValue {
    const gmxdata::OptionDef* def = nullptr;
    bool set = false;                   // option given on command line
    std::vector<std::string> values;    // raw string values (after conversion checks)
    // converted values
    std::vector<double> nums;
    bool boolValue = false;
    int enumIndex = -1;
    std::vector<std::string> enumValues;
};

class ParsedOptions {
public:
    const gmxdata::ModuleDef* module = nullptr;
    std::vector<OptionValue> values;      // one per option def
    double timeScale = 1.0;

    const OptionValue* find(const std::string& name) const;
    OptionValue* find(const std::string& name);
    bool isSet(const std::string& name) const;
    double real(const std::string& name) const;   // first numeric value or default
    int    integer(const std::string& name) const;
    bool   boolean(const std::string& name) const;
    std::string str(const std::string& name) const;
    std::string enumValue(const std::string& name) const;
    void   vector(const std::string& name, double out[3]) const;
    // Resolved file name for a file option (with extension completion); empty if not usable.
    std::string file(const std::string& name) const;
    std::vector<std::string> files(const std::string& name) const;
    // Whether the output/input file option should be used (set or required)
    bool fileSet(const std::string& name) const;
};

// Parse command line for a module; throws GmxError on failure.
ParsedOptions parseModuleOptions(const gmxdata::ModuleDef& mod, const std::vector<std::string>& args);
std::vector<std::string> extensionsFor(const gmxdata::OptionDef& def);
std::vector<std::string> enumValuesFor(const gmxdata::OptionDef& def);

// ---------------------------------------------------------------- modules
typedef int (*ModuleRunFunc)(const gmxdata::ModuleDef& mod, const std::vector<std::string>& args);
struct ModuleEntry {
    const char* name;
    ModuleRunFunc run;
};
ModuleRunFunc findModuleRunner(const std::string& name);
int runGenericModule(const gmxdata::ModuleDef& mod, const std::vector<std::string>& args);

// backup helper: makes "#name.N#" backup if file exists and backups enabled
void makeBackup(const std::string& fileName);
FILE* openOutputFile(const std::string& fileName);

// utilities
std::string baseName(const std::string& path);
bool fileExists(const std::string& path);
bool isRegularFile(const std::string& path);
std::string stripExtension(const std::string& name);
std::string extensionOf(const std::string& name);  // including dot, "" if none

const gmxdata::ModuleDef* findModuleDef(const std::string& name);

} // namespace gmx
EOF
echo done"}

