std::string baseName(const std::string& path)
{
    size_t p = path.find_last_of('/');
    if (p == std::string::npos) return path;
    return path.substr(p + 1);
}

bool fileExists(const std::string& path)
{
    struct stat st;
    return stat(path.c_str(), &st) == 0;
}

bool isRegularFile(const std::string& path)
{
    struct stat st;
    if (stat(path.c_str(), &st) != 0) return false;
    return S_ISREG(st.st_mode);
}

std::string extensionOf(const std::string& name)
{
    size_t slash = name.find_last_of('/');
    size_t dot   = name.find_last_of('.');
    if (dot == std::string::npos) return "";
    if (slash != std::string::npos && dot < slash) return "";
    return name.substr(dot);
}

std::string stripExtension(const std::string& name)
{
    std::string ext = extensionOf(name);
    return name.substr(0, name.size() - ext.size());
}

static std::string quoteArg(const std::string& a)
{
    if (a.find(' ') != std::string::npos) {
        return "'" + a + "'";
    }
    return a;
}

void initContext(int argc, char** argv)
{
    g_context.programName = argc > 0 ? baseName(argv[0]) : "gmx";
    char buf[PATH_MAX + 1];
    ssize_t n = readlink("/proc/self/exe", buf, PATH_MAX);
    if (n > 0) {
        buf[n] = '\0';
        g_context.fullPath = buf;
    } else if (argc > 0) {
        char* rp = realpath(argv[0], nullptr);
        if (rp) { g_context.fullPath = rp; free(rp); }
        else g_context.fullPath = argv[0];
    }
    char* cwd = getcwd(nullptr, 0);
    if (cwd) { g_context.workingDir = cwd; free(cwd); }
    std::string cl = g_context.programName;
    for (int i = 1; i < argc; ++i) {
        cl += " ";
        cl += quoteArg(argv[i]);
    }
    g_context.commandLine = cl;
    g_context.displayName = g_context.programName;
}

// ------------------------------------------------------------ text wrapping
std::string wrapText(const std::string& text, int width, int indent)
{
    std::string result;
    size_t start = 0;
    std::string ind(indent, ' ');
    while (start <= text.size()) {
        size_t nl = text.find('\n', start);
        std::string line = text.substr(start, nl == std::string::npos ? std::string::npos : nl - start);
        // determine existing leading whitespace of the line to preserve on continuation
        size_t lead = 0;
        while (lead < line.size() && line[lead] == ' ') ++lead;
        std::string prefix = ind + line.substr(0, lead);
        std::string body = line.substr(lead);
        // greedy wrap
        size_t pos = 0;
        bool first = true;
        if (body.empty()) {
            result += prefix;
            result += '\n';
        }
        while (pos < body.size()) {
            int avail = width - (int)prefix.size();
            if (avail < 1) avail = 1;
            std::string chunk;
            if ((int)(body.size() - pos) <= avail) {
                chunk = body.substr(pos);
                pos = body.size();
            } else {
                // find last space within avail
                size_t cut = body.rfind(' ', pos + avail);
                if (cut == std::string::npos || cut <= pos) {
                    // no space; find next space
                    size_t nsp = body.find(' ', pos);
                    if (nsp == std::string::npos) { chunk = body.substr(pos); pos = body.size(); }
                    else { chunk = body.substr(pos, nsp - pos); pos = nsp + 1; }
                } else {
                    chunk = body.substr(pos, cut - pos);
                    pos = cut + 1;
                }
                // skip extra spaces
                while (pos < body.size() && body[pos] == ' ') ++pos;
            }
            result += prefix;
            result += chunk;
            result += '\n';
            first = false;
        }
        (void)first;
        if (nl == std::string::npos) break;
        start = nl + 1;
    }
    return result;
}

