static unsigned int timeSeed()
{
    return (unsigned int)time(nullptr);
}

std::string chooseQuote()
{
    if (gmxdata::kNumQuotes <= 0) return "";
    // simple LCG seeded by time (seconds)
    unsigned long long s = timeSeed();
    s = s * 6364136223846793005ULL + 1442695040888963407ULL;
    s ^= s >> 33;
    s *= 0xff51afd7ed558ccdULL;
    s ^= s >> 33;
    int idx = (int)(s % (unsigned long long)gmxdata::kNumQuotes);
    return gmxdata::kQuotes[idx];
}

void printFooter(FILE* fp)
{
    std::string q = chooseQuote();
    fprintf(fp, "\nGROMACS reminds you: %s\n\n", q.c_str());
}

