            "The following paths were searched:\n"
            "  %s (current dir)\n"
            "  %s/share/gromacs/top (default)\n"
            "You can set additional directories to search with the GMXLIB path variable.",
            fileName.c_str(), g_context.workingDir.c_str(), kDataPrefix);
    return GmxError("System I/O error", "src/gromacs/utility/datafilefinder.cpp", 213,
                    "std::filesystem::__cxx11::path gmx::DataFileFinder::findFile(const gmx::DataFileOptions&) const",
                    msg);
}

void printError(FILE* fp, const GmxError& e)
{
    std::string out;
    out += "\n-------------------------------------------------------\n";
    out += formatString("Program:     %s, version %s\n", g_context.displayName.c_str(), kVersionString);
    if (!e.sourceFile.empty()) {
        out += formatString("Source file: %s (line %d)\n", e.sourceFile.c_str(), e.line);
    }
    if (!e.function.empty()) {
        out += formatString("Function:    %s\n", e.function.c_str());
