           "-------------------------------------------------------\n";
    fputs(out.c_str(), fp);
}

// ------------------------------------------------------------ backups
void makeBackup(const std::string& fileName)
{
    if (!g_settings.backup) return;
    if (!fileExists(fileName)) return;
    std::string dir = ".";
    std::string base = fileName;
    size_t slash = fileName.find_last_of('/');
    if (slash != std::string::npos) {
        dir = fileName.substr(0, slash);
        base = fileName.substr(slash + 1);
    }
    for (int i = 1; i < 99; ++i) {
        std::string bak = formatString("%s/#%s.%d#", dir.c_str(), base.c_str(), i);
        if (!fileExists(bak)) {
            if (rename(fileName.c_str(), bak.c_str()) == 0) {
                fprintf(stderr, "\nBack Off! I just backed up %s to %s\n", fileName.c_str(), bak.c_str());
            }
            return;
        }
    }
    throw fatalError(formatString("Won't make more than 99 backups of %s for you.\n"
                                  "The env.var. GMX_MAXBACKUP controls this maximum, -1 disables backups.",
                                  fileName.c_str()),
                     "src/gromacs/utility/futil.cpp", 329);
}

FILE* openOutputFile(const std::string& fileName)
{
    makeBackup(fileName);
    FILE* fp = fopen(fileName.c_str(), "w");
    if (!fp) {
        throw fileIOError(fileName, "src/gromacs/utility/futil.cpp", 458);
    }
    return fp;
}

