    std::string error;
};

static ConvertResult convertInt(const std::string& v, long long& out, bool is64 = false)
{
    ConvertResult r;
    if (v.empty()) { r.ok = false; r.error = formatString("Invalid value: '%s'; expected an integer", v.c_str()); return r; }
    errno = 0;
    char* end = nullptr;
    long long val = strtoll(v.c_str(), &end, 10);
    if (end == v.c_str() || *end != '\0') {
        r.ok = false; r.error = formatString("Invalid value: '%s'; expected an integer", v.c_str()); return r;
    }
    if (errno == ERANGE || (!is64 && (val > INT_MAX || val < INT_MIN))) {
        r.ok = false; r.error = formatString("Invalid value: '%s'; it causes an integer overflow", v.c_str()); return r;
    }
    out = val;
    return r;
}

static ConvertResult convertReal(const std::string& v, double& out)
{
    ConvertResult r;
    if (v.empty()) { r.ok = false; r.error = formatString("Invalid value: '%s'; expected a number", v.c_str()); return r; }
    errno = 0;
    char* end = nullptr;
    double val = strtod(v.c_str(), &end);
    if (end == v.c_str() || *end != '\0') {
        r.ok = false; r.error = formatString("Invalid value: '%s'; expected a number", v.c_str()); return r;
    }
    if (errno == ERANGE || std::isinf(val) || std::fabs(val) > FLT_MAX) {
        r.ok = false; r.error = formatString("Invalid value: '%s'; it causes an overflow/underflow", v.c_str()); return r;
    }
    out = (double)(float)val;
    return r;
}

static ConvertResult convertBool(const std::string& v, bool& out)
{
    ConvertResult r;
    if (!strcasecmp(v.c_str(), "1") || !strcasecmp(v.c_str(), "yes") || !strcasecmp(v.c_str(), "true")) { out = true; return r; }
    if (!strcasecmp(v.c_str(), "0") || !strcasecmp(v.c_str(), "no") || !strcasecmp(v.c_str(), "false")) { out = false; return r; }
    r.ok = false;
    r.error = formatString("Invalid value: '%s'; supported values are: 1, 0, yes, no, true, false", v.c_str());
    return r;
}

// Check an input file value; returns error message (empty if OK), and sets resolved name.
static std::string checkInputFile(const std::string& value, const std::vector<std::string>& exts,
                                  bool library, std::string& resolved)
{
    resolved = value;
    std::string ext = extensionOf(value);
    bool knownExt = false;
    for (const std::string& e : exts) if (e == ext) knownExt = true;
    if (fileExists(value)) {
        if (!isRegularFile(value)) {
            return formatString("Failed to access file '%s'.\nThe file is not a regular file.", value.c_str());
        }
        if (!knownExt) {
            return formatString("File '%s' cannot be used by GROMACS because it does not have a recognizable extension.\n"
                                "The following extensions are possible for this option:\n  %s",
                                value.c_str(), joinExts(exts).c_str());
        }
        FILE* fp = fopen(value.c_str(), "r");
        if (!fp) {
            int err = errno;
            return formatString("Failed to access file '%s'.\nThe file could not be opened.\n  Reason: %s\n  (call to fopen() returned error code %d)",
                                value.c_str(), strerror(err), err);
        }
        fclose(fp);
        return "";
    }
    if (knownExt) {
        if (library) {
            return formatString("Library file '%s' not found in current dir nor in the default directories.\n"
                                "The following paths were searched:\n  %s (current dir)\n  %s/share/gromacs/top (default)\n"
                                "You can set additional directories to search with the GMXLIB path variable.",
                                value.c_str(), g_context.workingDir.c_str(), kDataPrefix);
        }
        return formatString("File '%s' does not exist or is not accessible.\nThe file could not be opened.\n  Reason: No such file or directory\n  (call to fopen() returned error code 2)",
                            value.c_str());
    }
    // try completing extension
    for (const std::string& e : exts) {
        std::string cand = value + e;
        if (fileExists(cand) && isRegularFile(cand)) {
            resolved = cand;
            return "";
        }
    }
    return formatString("File '%s' does not exist or is not accessible.\nThe following extensions were tried to complete the file name:\n  %s",
                        value.c_str(), joinExts(exts).c_str());
}

static std::string completeOutputFile(const std::string& value, const gmxdata::OptionDef& def)
{
    std::vector<std::string> exts = extensionsFor(def);
    std::string ext = extensionOf(value);
    for (const std::string& e : exts) if (e == ext) return value;
    // append default extension
    std::string defExt;
    if (def.def) defExt = extensionOf(def.def);
    if (defExt.empty() && !exts.empty()) defExt = exts[0];
    return value + defExt;
}

static std::string indentLines(const std::string& text, int n)
{
    std::string ind(n, ' ');
    std::string out;
    size_t p = 0;
    while (p <= text.size()) {
        size_t q = text.find('\n', p);
        out += ind + text.substr(p, q == std::string::npos ? std::string::npos : q - p) + "\n";
        if (q == std::string::npos) break;
        p = q + 1;
    }
    if (!out.empty() && out.back() == '\n') out.pop_back();
    return out;
}

// ---------------------------------------------------------------- ParsedOptions
const OptionValue* ParsedOptions::find(const std::string& name) const
{
    for (const OptionValue& v : values) if (name == v.def->name) return &v;
    return nullptr;
}
OptionValue* ParsedOptions::find(const std::string& name)
{
    for (OptionValue& v : values) if (name == v.def->name) return &v;
    return nullptr;
}
bool ParsedOptions::isSet(const std::string& name) const
{
    const OptionValue* v = find(name);
    return v && v->set;
}
double ParsedOptions::real(const std::string& name) const
{
    const OptionValue* v = find(name);
    if (!v) return 0;
    if (!v->nums.empty()) return v->nums[0];
    if (v->def->def) return atof(v->def->def);
    return 0;
}
int ParsedOptions::integer(const std::string& name) const
{
    const OptionValue* v = find(name);
    if (!v) return 0;
    if (!v->nums.empty()) return (int)v->nums[0];
    if (v->def->def) return atoi(v->def->def);
    return 0;
}
bool ParsedOptions::boolean(const std::string& name) const
{
    const OptionValue* v = find(name);
    if (!v) return false;
    if (v->set) return v->boolValue;
    return v->def && !strcmp(v->def->def, "yes");
}
std::string ParsedOptions::str(const std::string& name) const
{
    const OptionValue* v = find(name);
    if (!v) return "";
    if (!v->values.empty()) return v->values[0];
    return v->def->def ? v->def->def : "";
}
std::string ParsedOptions::enumValue(const std::string& name) const
{
    const OptionValue* v = find(name);
    if (!v) return "";
    if (v->enumIndex >= 0) return v->enumValues[v->enumIndex];
    return v->def->def ? v->def->def : "";
}
void ParsedOptions::vector(const std::string& name, double out[3]) const
{
    out[0] = out[1] = out[2] = 0;
    const OptionValue* v = find(name);
    if (!v) return;
    if (v->nums.size() == 3) { out[0] = v->nums[0]; out[1] = v->nums[1]; out[2] = v->nums[2]; return; }
    if (v->nums.size() == 1) { out[0] = out[1] = out[2] = v->nums[0]; return; }
    if (v->def->def) {
        std::vector<std::string> w = splitWords(v->def->def);
        for (size_t i = 0; i < w.size() && i < 3; ++i) out[i] = atof(w[i].c_str());
    }
}
std::string ParsedOptions::file(const std::string& name) const
{
    std::vector<std::string> f = files(name);
    return f.empty() ? "" : f[0];
}
std::vector<std::string> ParsedOptions::files(const std::string& name) const
{
    std::vector<std::string> out;
    const OptionValue* v = find(name);
    if (!v) return out;
    if (!v->values.empty()) return v->values;
    if (v->def->def) {
        if (v->def->section == 0 || v->def->section == 2) {
            // input: resolve default with extension completion
            std::string base = stripExtension(v->def->def);
            for (const std::string& e : extensionsFor(*v->def)) {
                if (fileExists(base + e)) { out.push_back(base + e); return out; }
            }
            out.push_back(v->def->def);
        } else {
            out.push_back(v->def->def);
        }
    }
    return out;
}
bool ParsedOptions::fileSet(const std::string& name) const
{
    const OptionValue* v = find(name);
    if (!v) return false;
    if (v->set) return true;
    return !v->def->optional;
}

// ---------------------------------------------------------------- parser
ParsedOptions parseModuleOptions(const gmxdata::ModuleDef& mod, const std::vector<std::string>& args)
{
    ParsedOptions po;
    po.module = &mod;
    for (int i = 0; i < mod.numOptions; ++i) {
        OptionValue v;
        v.def = &mod.options[i];
        if (v.def->kind == 'e') v.enumValues = enumValuesFor(*v.def);
        po.values.push_back(v);
    }

    std::vector<std::string> errors;
    OptionValue* cur = nullptr;
    bool skip = false;
    bool curErrored = false;
    bool curNegated = false;
    std::string curDisplay;

    auto addError = [&](const std::string& optDisplay, const std::string& msg) {
        errors.push_back("  In command-line option " + optDisplay + "\n" + indentLines(msg, 4));
    };
    auto maxValues = [&](const OptionValue* v) -> int {
        switch (v->def->kind) {
            case 'b': return 1;
            case 'v': return 3;
            case 'S': return 1000000;
            case 'F': return v->def->multi ? 1000000 : 1;
            default: return 1;
        }
    };
    auto minValues = [&](const OptionValue* v) -> int {
        switch (v->def->kind) {
            case 'b': return 0;
            case 'F': return (v->def->def ? 0 : 1);
            case 'S': return 0;
            default: return 1;
        }
    };
    auto finishCurrent = [&]() {
        if (!cur) return;
        if (!curErrored) {
            if ((int)cur->values.size() < minValues(cur)) {
                if (cur->def->kind == 'f') addError(curDisplay, "No file name provided");
                else addError(curDisplay, "Too few (valid) values");
            } else if (cur->def->kind == 'v' && cur->values.size() == 2) {
                addError(curDisplay, "Expected 1 or 3 values, got 2");
            }
        }
        if (cur->def->kind == 'b' && cur->values.empty()) {
            cur->boolValue = !curNegated;
        }
        cur = nullptr;
    };

    for (size_t ai = 0; ai < args.size(); ++ai) {
        const std::string& arg = args[ai];
        if (isOptionArg(arg)) {
            finishCurrent();
            std::string name = arg;
            if (name.compare(0, 2, "--") == 0) name = name.substr(2);
            else name = name.substr(1);
            OptionValue* v = po.find(name);
            bool negated = false;
            if (!v && name.compare(0, 2, "no") == 0) {
                OptionValue* v2 = po.find(name.substr(2));
                if (v2 && v2->def->kind == 'b') { v = v2; negated = true; }
            }
            if (!v) {
                errors.push_back("    Unknown command-line option " + arg);
                skip = true;
                continue;
            }
            curDisplay = "-" + name;
            if (v->set) {
                addError(curDisplay, "Option specified multiple times");
                skip = true;
                continue;
            }
            v->set = true;
            cur = v;
            skip = false;
            curErrored = false;
            curNegated = negated;
            continue;
        }
        // value
        if (skip) continue;
        if (!cur) {
            throw userInputError(formatString("Positional argument '%s' cannot be accepted. Perhaps you forgot to put a hyphen before an option name.",
                                              arg.c_str()), kParserFile, kParserLine, kParserFunc);
        }
        // convert
        std::string err;
        std::string stored = arg;
        switch (cur->def->kind) {
            case 'b': {
                if (curNegated) { err = "Cannot specify a value together with 'no' prefix"; break; }
                bool b;
                ConvertResult r = convertBool(arg, b);
                if (!r.ok) err = r.error; else cur->boolValue = b;
                break;
            }
            case 'i': {
                long long iv;
                ConvertResult r = convertInt(arg, iv);
                if (!r.ok) err = r.error; else cur->nums.push_back((double)iv);
                break;
            }
            case 'r': case 't': case 'v': {
                double d;
                ConvertResult r = convertReal(arg, d);
                if (!r.ok) err = r.error; else cur->nums.push_back(d);
                break;
            }
            case 'e': {
                int match = -1;
                for (size_t k = 0; k < cur->enumValues.size(); ++k) {
                    if (cur->enumValues[k].compare(0, arg.size(), arg) == 0) { match = (int)k; break; }
                }
                if (match < 0) {
                    std::string allowed;
                    for (size_t k = 0; k < cur->enumValues.size(); ++k) {
                        if (k) allowed += ", ";
                        allowed += cur->enumValues[k];
                    }
                    err = formatString("Invalid value: %s. Allowed values: %s.", arg.c_str(), allowed.c_str());
                } else {
                    cur->enumIndex = match;
                    stored = cur->enumValues[match];
                }
                break;
            }
            case 'F': {
                if (cur->def->section == 0) {
                    std::string resolved;
                    err = checkInputFile(arg, extensionsFor(*cur->def), cur->def->library, resolved);
                    stored = resolved;
                } else {
                    stored = completeOutputFile(arg, *cur->def);
                }
                break;
            }
            default:
                break;
        }
        if (!err.empty()) {
            addError(curDisplay, err);
            curErrored = true;
            continue;
        }
        if ((int)cur->values.size() >= maxValues(cur)) {
            addError(curDisplay, "Too many values");
            continue;
        }
        cur->values.push_back(stored);
    }
    finishCurrent();

    if (!errors.empty()) {
        std::string msg = "Invalid command-line options\n";
        for (size_t i = 0; i < errors.size(); ++i) {
            msg += errors[i];
            if (i + 1 < errors.size()) msg += "\n";
        }
        throw userInputError(msg, kParserFile, kParserLine, kParserFunc);
    }

    // finish stage: required input files / defaults
    std::vector<std::string> ferrors;
    for (OptionValue& v : po.values) {
        if (v.def->kind != 'F') continue;
        if (v.def->section != 0 && v.def->section != 2) continue;
        if (!v.values.empty()) continue;
        bool required = !v.def->optional;
        if (!v.set && !required) continue;
        if (!v.def->def) continue;
        std::string base = stripExtension(v.def->def);
        std::vector<std::string> exts = extensionsFor(*v.def);
        bool found = false;
        for (const std::string& e : exts) {
            if (fileExists(base + e) && isRegularFile(base + e)) { found = true; break; }
        }
        if (found) continue;
        if (v.def->library) {
            // library files are looked up in data directories, which we do not have
            continue;
        }
        std::string msg;
        if (v.set) {
            msg = formatString("No file name was provided, and the default file '%s' does not exist or is not accessible.", base.c_str());
        } else {
            msg = formatString("Required option was not provided, and the default file '%s' does not exist or is not accessible.", base.c_str());
        }
        msg += "\nThe following extensions were tried to complete the file name:\n  " + joinExts(exts);
        ferrors.push_back(formatString("  In option %s\n", v.def->name) + indentLines(msg, 4));
    }
    if (!ferrors.empty()) {
        std::string msg = "Invalid input values\n";
        for (size_t i = 0; i < ferrors.size(); ++i) {
            msg += ferrors[i];
            if (i + 1 < ferrors.size()) msg += "\n";
        }
        throw userInputError(msg, kFinishFile, kFinishLine, kFinishFunc);
    }
    return po;
}

} // namespace gmx
EOF
