const gmxdata::ModuleDef kCommonModule = {"", "", kCommonOptions, 6};

void applyCommon(const ParsedOptions& po)
{
    if (po.isSet("h")) g_settings.help = po.boolean("h");
    if (po.isSet("quiet")) g_settings.quiet = po.boolean("quiet");
    if (po.isSet("version")) g_settings.version = po.boolean("version");
    if (po.isSet("copyright")) g_settings.copyright = po.boolean("copyright");
    if (po.isSet("nice")) g_settings.nice = po.integer("nice");
    if (po.isSet("backup")) g_settings.backup = po.boolean("backup");
}

// Parse the common options from args. Unknown options (and their values) are
// collected into 'remaining' when skipUnknown is true.
void parseCommon(const std::vector<std::string>& args, bool skipUnknown, std::vector<std::string>& remaining)
{
    // Split args into common-option groups and other groups.
    std::vector<std::string> commonArgs;
    bool inUnknown = false;
    for (const std::string& a : args) {
        bool isOpt = a.size() >= 2 && a[0] == '-';
        if (isOpt) {
            // decide if option (same rule as parser)
            char* end = nullptr;
            strtod(a.c_str(), &end);
            bool numeric = end && *end == '\0';
            bool allDash = a.find_first_not_of('-') == std::string::npos;
            isOpt = !numeric && !allDash;
        }
        if (isOpt) {
            std::string name = a;
            if (name.compare(0, 2, "--") == 0) name = name.substr(2); else name = name.substr(1);
            bool known = false;
            for (const gmxdata::OptionDef& d : kCommonOptions) {
                if (name == d.name || (d.kind == 'b' && name == std::string("no") + d.name)) known = true;
            }
            if (known || !skipUnknown) {
                inUnknown = false;
                commonArgs.push_back(a);
            } else {
                inUnknown = true;
                remaining.push_back(a);
            }
        } else {
            if (inUnknown) remaining.push_back(a);
            else commonArgs.push_back(a);
        }
    }
    ParsedOptions po = parseModuleOptions(kCommonModule, commonArgs);
    applyCommon(po);
}

void printVersionInfo(FILE* fp)
{
    printHeader(fp, g_settings.copyright);
    fputs("\n", fp);
    fputs(gmxdata::k_versioninfo, fp);
}

const gmxdata::TopicDef* findTopic(const std::string& name)
{
    for (const gmxdata::TopicDef* t = gmxdata::kTopics; t->name; ++t) {
        if (name == t->name) return t;
    }
    return nullptr;
}

int runHelpModule(const std::vector<std::string>& args)
{
    // args: topics
    if (args.empty()) {
        fputs(findTopic("help")->text, stdout);
        return 0;
    }
    const std::string& first = args[0];
    if (first == "commands" || first == "selections") {
        if (args.size() == 1) {
            fputs(findTopic(first)->text, stdout);
            return 0;
        }
        if (first == "commands") {
            fprintf(stderr, "Help topic 'commands' has no subtopics\n");
            return 2;
        }
        const gmxdata::TopicDef* sub = findTopic("sel_" + args[1]);
        if (!sub) {
            fprintf(stderr, "Help topic 'selections' has no subtopic '%s'\n", args[1].c_str());
            return 2;
        }
        if (args.size() > 2) {
            fprintf(stderr, "Help topic '%s' has no subtopics\n", args[1].c_str());
            return 2;
        }
        fputs(sub->text, stdout);
        return 0;
    }
    if (first == "help") {
        if (args.size() > 1) {
            fprintf(stderr, "Help topic 'help' has no subtopics\n");
            return 2;
        }
        fputs(findTopic("help_help")->text, stdout);
        return 0;
    }
    const gmxdata::ModuleDef* mod = findModuleDef(first);
    if (!mod) {
        fprintf(stderr, "No help available for '%s'\n", first.c_str());
        return 2;
    }
    if (args.size() > 1) {
        fprintf(stderr, "Help topic '%s' has no subtopics\n", first.c_str());
        return 2;
    }
    fputs(mod->helpText, stdout);
    return 0;
}

} // namespace

int main(int argc, char** argv)
{
    initContext(argc, argv);
    std::vector<std::string> args(argv + 1, argv + argc);

    // Locate module name: first argument not starting with '-'.
    size_t modIdx = args.size();
    for (size_t i = 0; i < args.size(); ++i) {
        if (args[i].empty() || args[i][0] != '-') { modIdx = i; break; }
    }
    std::vector<std::string> globalArgs(args.begin(), args.begin() + modIdx);
    std::string moduleName = modIdx < args.size() ? args[modIdx] : "";
    std::vector<std::string> moduleArgs;
    if (modIdx < args.size()) moduleArgs.assign(args.begin() + modIdx + 1, args.end());

    try {
        std::vector<std::string> dummy;
        parseCommon(globalArgs, false, dummy);
    } catch (const GmxError& e) {
        if (!g_settings.quiet) printHeader(stderr, g_settings.copyright);
        printError(stderr, e);
        return e.exitCode;
    }

    if (g_settings.version) {
        printVersionInfo(stdout);
        return 0;
    }
    if (g_settings.help || moduleName.empty()) {
        if (!g_settings.quiet) { printHeader(stderr, g_settings.copyright); fputs("\n", stderr); }
        fputs(findTopic("help")->text, stdout);
        if (!g_settings.quiet) printFooter(stderr);
        return 0;
    }

    bool isHelp = (moduleName == "help");
    const gmxdata::ModuleDef* mod = isHelp ? nullptr : findModuleDef(moduleName);
    if (!isHelp && !mod) {
        if (!g_settings.quiet) printHeader(stderr, g_settings.copyright);
        GmxError e = userInputError(formatString("'%s' is not a GROMACS command.", moduleName.c_str()),
                                    "src/gromacs/commandline/cmdlinemodulemanager.cpp", 389,
                                    "gmx::ICommandLineModule* gmx::CommandLineModuleManager::Impl::processCommonOptions(gmx::CommandLineCommonOptionsHolder*, int*, char***)");
        printError(stderr, e);
        return 1;
    }
    g_context.displayName = "gmx " + moduleName;

    std::vector<std::string> remaining;
    try {
        parseCommon(moduleArgs, true, remaining);
    } catch (const GmxError& e) {
        if (!g_settings.quiet) printHeader(stderr, g_settings.copyright);
        printError(stderr, e);
        return e.exitCode;
    }
    if (g_settings.version) {
        printVersionInfo(stdout);
        return 0;
    }
    if (!g_settings.quiet) { printHeader(stderr, g_settings.copyright); fputs("\n", stderr); }
    if (g_settings.nice != 0) {
        if (nice(g_settings.nice) == -1) { /* ignore */ }
    }

    int rc = 0;
    if (g_settings.help) {
        if (isHelp) fputs(findTopic("help_help")->text, stdout);
        else fputs(mod->helpText, stdout);
    } else {
        try {
            if (isHelp) {
                rc = runHelpModule(remaining);
            } else {
                ModuleRunFunc fn = findModuleRunner(moduleName);
                if (!fn) fn = runGenericModule;
                rc = fn(*mod, remaining);
            }
        } catch (const GmxError& e) {
            fflush(stdout);
            printError(stderr, e);
            return e.exitCode;
        }
    }
    if (!g_settings.quiet) printFooter(stderr);
    return rc;
}
