// Module registry and generic fallback behaviour.
#include "gmx.h"

namespace gmx {

int runSigeps(const gmxdata::ModuleDef& mod, const std::vector<std::string>& args);
int runGenconf(const gmxdata::ModuleDef& mod, const std::vector<std::string>& args);
int runCheck(const gmxdata::ModuleDef& mod, const std::vector<std::string>& args);

static const ModuleEntry kEntries[] = {
    {"sigeps", runSigeps},
    {"genconf", runGenconf},
    {"check", runCheck},
    {nullptr, nullptr},
};

ModuleRunFunc findModuleRunner(const std::string& name)
{
    for (const ModuleEntry* e = kEntries; e->name; ++e) {
        if (name == e->name) return e->run;
    }
    return nullptr;
}

int runGenericModule(const gmxdata::ModuleDef& mod, const std::vector<std::string>& args)
{
    ParsedOptions po = parseModuleOptions(mod, args);
    (void)po;
    return 0;
}

