// gmx sigeps: convert C6/C12 or C6/Cn combinations to and from sigma/epsilon.
#include "gmx.h"
#include "xvg.h"
#include <cmath>

namespace gmx {

namespace {
const float ONE_4PI_EPS0 = 138.935458f;

float pot(float x, float qq, float c6, float cn, int npow)
{
    return cn * std::pow(x, (float)-npow) - c6 / std::pow(x, 6.0f) + qq * ONE_4PI_EPS0 / x;
}

float bhpot(float x, float A, float B, float C)
{
    return A * std::exp(-B * x) - C / std::pow(x, 6.0f);
}

float dpot(float x, float qq, float c6, float cn, int npow)
{
    return -(npow * cn * std::pow(x, (float)(-npow - 1)) - 6 * c6 / (x * std::pow(x, 6.0f)) + qq * ONE_4PI_EPS0 / (x * x));
}
} // namespace

int runSigeps(const gmxdata::ModuleDef& mod, const std::vector<std::string>& args)
{
    ParsedOptions po = parseModuleOptions(mod, args);

    float c6  = (float)po.real("c6");
    float cn  = (float)po.real("cn");
    int   npow = po.integer("pow");
    float sig = (float)po.real("sig");
    float eps = (float)po.real("eps");
    float Abh = (float)po.real("A");
    float Bbh = (float)po.real("B");
    float Cbh = (float)po.real("C");
    float qi  = (float)po.real("qi");
    float qj  = (float)po.real("qj");
    float sigfac = (float)po.real("sigfac");
    XvgFormat fmt = xvgFormatFromString(po.enumValue("xvg"));

    bool bBham = po.isSet("A") || po.isSet("B") || po.isSet("C");
    float minimum;
    if (bBham) {
        c6  = Cbh;
        sig = std::pow((6.0 / npow) * std::pow(npow / Bbh, npow - 6.0), 1.0 / (npow - 6.0));
        eps = c6 / (4 * std::pow(sig, 6.0));
        cn  = 4 * eps * std::pow(sig, (float)npow);
    } else {
        if (po.isSet("sig") || po.isSet("eps")) {
            c6 = 4 * eps * std::pow(sig, 6.0);
            cn = 4 * eps * std::pow(sig, (float)npow);
        } else if (po.isSet("c6") || po.isSet("cn") || po.isSet("pow")) {
            sig = std::pow(cn / c6, 1.0 / (npow - 6.0));
            eps = c6 / (4 * std::pow(sig, 6.0));
        } else {
            sig = eps = 0;
        }
        printf("c6    = %12.5e, c%d    = %12.5e\n", c6, npow, cn);
        printf("sigma = %12.5f, epsilon = %12.5f\n", sig, eps);

        minimum = std::pow(npow / 6.0 * std::pow(sig, npow - 6.0), 1.0 / (npow - 6));
        printf("Van der Waals minimum at %g, V = %g\n\n", minimum, pot(minimum, 0, c6, cn, npow));
        printf("Fit of Lennard Jones (%d-6) to Buckingham:\n", npow);
        Bbh = npow / minimum;
        Abh = cn * std::exp(Bbh * minimum) / std::pow(minimum, (float)npow);
        printf("A = %g, B = %g, C = %g\n", Abh, Bbh, c6);
    }
    float qq = qi * qj;

    std::string fn = po.file("o");
    FILE* fp = xvgrOpen(fn, "Potential", "r (nm)", "E (kJ/mol)", fmt, "gmx sigeps");
    xvgrLegend(fp, {"Lennard-Jones", "Buckingham"}, fmt);
    if (sig == 0) sig = 0.25;
    float dp[2] = {0, 0};
    int cur = 0, next = 1;
    float oldx = 0;
    for (int i = 0; i < 100; ++i) {
        float x = sigfac * sig + sig * i * 0.02f;
        dp[next] = dpot(x, qq, c6, cn, npow);
        fprintf(fp, "%10g  %10g  %10g\n", x, pot(x, qq, c6, cn, npow), bhpot(x, Abh, Bbh, Cbh));
        if (qq != 0) {
            if (i > 0 && dp[cur] * dp[next] < 0) {
                float m = oldx + dp[cur] * (x - oldx) / (dp[cur] - dp[next]);
                float mval = pot(m, qq, c6, cn, npow);
                printf("Van der Waals + Coulomb minimum at r = %g (nm). Value = %g (kJ/mol)\n", m, mval);
            }
        }
        cur  = next;
        next = 1 - cur;
        oldx = x;
    }
    fclose(fp);

    if (po.boolean("w")) {
        const char* disp = getenv("DISPLAY");
        if (!disp || !*disp) {
            fprintf(stderr, "Can not view %s, no DISPLAY environment variable.\n", fn.c_str());
        }
    }
    return 0;
}

} // namespace gmx
