};

ModuleRunFunc findModuleRunner(const std::string& name)
{
    for (const ModuleEntry* e = kEntries; e->name; ++e) {
        if (name == e->name) return e->run;
    }
    return nullptr;
}

int runGenericModule(const gmxdata::ModuleDef& mod, const std::vector<std::string>& args)
{
    ParsedOptions po = parseModuleOptions(mod, args);
    return runStructureTool(mod, args);
}

// Trajectory analysis framework modules: require either -f or -s.
int runTrajAnalysis(const gmxdata::ModuleDef& mod, const std::vector<std::string>& args)
{
    ParsedOptions po = parseModuleOptions(mod, args);
    if (!po.isSet("f") && !po.isSet("s")) {
        throw GmxError("Inconsistency in user input", "src/gromacs/trajectoryanalysis/runnercommon.cpp", 403,
                       "void gmx::TrajectoryAnalysisRunnerCommon::optionsFinished()",
                       "No trajectory or topology provided, nothing to do!");
    }
    if (po.isSet("s")) {
        // Reading a structure requires the residue type database from the data directory.
        throw libraryFileNotFound("residuetypes.dat");
    }
    return 0;
}

int runBar(const gmxdata::ModuleDef& mod, const std::vector<std::string>& args)
{
    ParsedOptions po = parseModuleOptions(mod, args);
    if (!po.isSet("f") && !po.isSet("g")) {
        throw fatalError("No input files!", "src/gromacs/gmxana/gmx_bar.cpp", 3515);
    }
    return 0;
}

int runWham(const gmxdata::ModuleDef& mod, const std::vector<std::string>& args)
{
    ParsedOptions po = parseModuleOptions(mod, args);
    bool ix = po.isSet("ix"), ifl = po.isSet("if");
    if (ix == ifl) {
        throw fatalError("Give either pullx (-ix) OR pullf (-if) data. Not both.", "src/gromacs/gmxana/gmx_wham.cpp", 3194);
    }
    return 0;
}

int runSolvate(const gmxdata::ModuleDef& mod, const std::vector<std::string>& args)
{
    ParsedOptions po = parseModuleOptions(mod, args);
    if (!po.isSet("cp") && !po.isSet("box")) {
        throw fatalError("When no solute (-cp) is specified, a box size (-box) must be specified",
                         "src/gromacs/gmxpreprocess/solvate.cpp", 984);
    }
    throw libraryFileNotFound("residuetypes.dat");
}

int runMakeNdx(const gmxdata::ModuleDef& mod, const std::vector<std::string>& args)
{
    ParsedOptions po = parseModuleOptions(mod, args);
    if (!po.isSet("f") && !po.isSet("n")) {
        throw fatalError("No input files (structure or index)", "src/gromacs/tools/make_ndx.cpp", 1478);
    }
    if (po.isSet("f")) {
        fprintf(stderr, "Reading structure file\n");
        throw libraryFileNotFound("residuetypes.dat");
    }
    return 0;
}

int runDump(const gmxdata::ModuleDef& mod, const std::vector<std::string>& args)
{
    ParsedOptions po = parseModuleOptions(mod, args);
    if (po.isSet("f")) {
        std::string fn = po.file("f");
        std::string ext = extensionOf(fn);
        if (ext == ".gro" || ext == ".pdb" || ext == ".g96") {
            printf("File %s is of an unsupported type. Try using the command\n 'less %s'\n", fn.c_str(), fn.c_str());
            return 0;
        }
    }
    return 0;
}

int runX2top(const gmxdata::ModuleDef& mod, const std::vector<std::string>& args)
{
    ParsedOptions po = parseModuleOptions(mod, args);
    if (!po.isSet("o") && !po.isSet("r")) {
        throw fatalError("Specify at least one output file", "src/gromacs/gmxpreprocess/x2top.cpp", 499);
    }
    throw libraryFileNotFound("residuetypes.dat");
}

// Legacy tools that read a structure file: without the GROMACS data files
// installed, reading residue information fails.
int runStructureTool(const gmxdata::ModuleDef& mod, const std::vector<std::string>& args)
{
    ParsedOptions po = parseModuleOptions(mod, args);
    std::string name = mod.name;
    if (name == "confrms") {
        fprintf(stderr, "Reading first structure file\n");
        throw libraryFileNotFound("residuetypes.dat");
    }
    if (name == "genrestr") {
        fprintf(stderr, "Reading structure file\n");
        throw libraryFileNotFound("residuetypes.dat");
    }
    if (name == "editconf" || name == "insert-molecules" || name == "pdb2gmx" || name == "genion"
        || name == "trjorder" || name == "make_edi" || name == "mk_angndx") {
        if (name == "insert-molecules") fprintf(stderr, "Initialising inter-atomic distances...\n");
        throw libraryFileNotFound("residuetypes.dat");
    }
    // Tools with a structure (-s) option from read_tps_conf
    for (int i = 0; i < mod.numOptions; ++i) {
        const gmxdata::OptionDef& d = mod.options[i];
        if (d.kind == 'F' && d.section == 0 && std::strcmp(d.name, "s") == 0 && po.fileSet("s")) {
            std::string ext = extensionOf(po.file("s"));
            if (ext == ".gro" || ext == ".pdb" || ext == ".g96" || ext == ".brk" || ext == ".ent") {
                throw libraryFileNotFound("residuetypes.dat");
            }
        }
    }
    return 0;
}

} // namespace gmx
