            pos += ddist;
        }
        if (line.size() >= pos + 3 * (ddist)) {
            int vdist = ddist;
            bool ok = true;
            for (int d = 0; d < 3; ++d) {
                std::string s = line.substr(pos, vdist);
                if (trim(s).empty()) ok = false;
                a.v[d] = atof(s.c_str());
                pos += vdist;
            }
            if (ok) fr.hasVelocities = true;
        }
    }
    if (!getLine(fp, line)) { if (error) *error = "Unexpected end of file"; return false; }
    {
        std::vector<double> b;
        char* s = const_cast<char*>(line.c_str());
        char* end;
        while (true) {
            double v = strtod(s, &end);
            if (end == s) break;
            b.push_back(v);
            s = end;
        }
        if (b.size() >= 3) {
            fr.hasBox = true;
            fr.box[0][0] = b[0]; fr.box[1][1] = b[1]; fr.box[2][2] = b[2];
            if (b.size() >= 9) {
                fr.box[0][1] = b[3]; fr.box[0][2] = b[4];
                fr.box[1][0] = b[5]; fr.box[1][2] = b[6];
                fr.box[2][0] = b[7]; fr.box[2][1] = b[8];
            }
        }
    }
    return true;
}

// ------------------------------------------------------------------ pdb
static bool readPdbFrames(FILE* fp, std::vector<Frame>& frames, std::string* error)
{
    std::string line;
    Frame fr;
    bool haveAtoms = false;
    int serial = 0;
    while (getLine(fp, line)) {
        std::string rec = line.substr(0, 6);
        if (rec.compare(0, 5, "TITLE") == 0) {
            std::string t = trim(line.size() > 10 ? line.substr(10) : "");
            if (fr.title.empty()) fr.title = t;
        } else if (rec.compare(0, 6, "CRYST1") == 0 && line.size() >= 54) {
            double a = atof(line.substr(6, 9).c_str()) / 10.0;
            double b = atof(line.substr(15, 9).c_str()) / 10.0;
            double c = atof(line.substr(24, 9).c_str()) / 10.0;
            double alpha = atof(line.substr(33, 7).c_str());
            double beta  = atof(line.substr(40, 7).c_str());
            double gamma = atof(line.substr(47, 7).c_str());
            const double DEG2RAD = M_PI / 180.0;
            fr.hasBox = true;
            fr.box[0][0] = a;
            if (fabs(alpha - 90) < 1e-6 && fabs(beta - 90) < 1e-6 && fabs(gamma - 90) < 1e-6) {
                fr.box[1][1] = b; fr.box[2][2] = c;
            } else {
                double cosa = cos(alpha * DEG2RAD), cosb = cos(beta * DEG2RAD), cosg = cos(gamma * DEG2RAD), sing = sin(gamma * DEG2RAD);
                fr.box[1][0] = b * cosg; fr.box[1][1] = b * sing;
                fr.box[2][0] = c * cosb;
                fr.box[2][1] = c * (cosa - cosb * cosg) / sing;
                fr.box[2][2] = sqrt(c * c - fr.box[2][0] * fr.box[2][0] - fr.box[2][1] * fr.box[2][1]);
            }
        } else if (rec.compare(0, 4, "ATOM") == 0 || rec.compare(0, 6, "HETATM") == 0) {
            if (line.size() < 54) continue;
            Atom a;
            a.pdbRecord = rec.compare(0, 4, "ATOM") == 0 ? "ATOM" : "HETATM";
            a.atomnr = atoi(line.substr(6, 5).c_str());
            ++serial;
            a.atomname = trim(line.substr(12, 4));
            a.altloc = line[16];
            a.resname = trim(line.substr(17, 4));
            a.chain = line[21];
            a.resnr = atoi(line.substr(22, 4).c_str());
            a.x[0] = atof(line.substr(30, 8).c_str()) / 10.0;
            a.x[1] = atof(line.substr(38, 8).c_str()) / 10.0;
            a.x[2] = atof(line.substr(46, 8).c_str()) / 10.0;
            if (line.size() >= 60) a.occupancy = atof(line.substr(54, 6).c_str());
            if (line.size() >= 66) a.bfactor = atof(line.substr(60, 6).c_str());
            if (line.size() >= 78) a.element = trim(line.substr(76, 2));
            fr.atoms.push_back(a);
            haveAtoms = true;
        } else if (rec.compare(0, 6, "ENDMDL") == 0 || rec.compare(0, 3, "END") == 0) {
            if (haveAtoms) {
                frames.push_back(fr);
                Frame nf;
                nf.title = fr.title;
                nf.hasBox = fr.hasBox;
                memcpy(nf.box, fr.box, sizeof(nf.box));
                fr = nf;
                fr.atoms.clear();
                haveAtoms = false;
            }
        }
    }
    if (haveAtoms) frames.push_back(fr);
    if (frames.empty()) { if (error) *error = "No atoms found"; return false; }
    return true;
}

bool readStructureFrames(const std::string& fileName, std::vector<Frame>& frames, std::string* error)
{
    FILE* fp = fopen(fileName.c_str(), "r");
    if (!fp) { if (error) *error = "Could not open file"; return false; }
    std::string type = fileTypeName(fileName);
    bool ok = true;
    if (type == "gro") {
        Frame fr;
        while (readGroFrame(fp, fr, error)) frames.push_back(fr);
        ok = !frames.empty();
    } else if (type == "pdb" || type == "brk" || type == "ent") {
        ok = readPdbFrames(fp, frames, error);
    } else {
        if (error) *error = "Unsupported file type";
        ok = false;
    }
    fclose(fp);
    return ok;
}

bool readStructure(const std::string& fileName, Frame& frame, std::string* error)
{
    std::vector<Frame> frames;
    if (!readStructureFrames(fileName, frames, error)) return false;
    frame = frames[0];
    return true;
}

// ------------------------------------------------------------------ writing
void writeGro(FILE* fp, const Frame& fr, bool writeVelocities, int decimals)
{
    std::string title = fr.title;
    if (fr.hasTime) {
        // keep as-is
    }
    fprintf(fp, "%s\n", title.c_str());
    fprintf(fp, "%5d\n", (int)fr.atoms.size());
    int w = decimals + 5;
    std::string xfmt = formatString("%%%d.%df", w, decimals);
    std::string vfmt = formatString("%%%d.%df", w, decimals + 1);
    for (size_t i = 0; i < fr.atoms.size(); ++i) {
        const Atom& a = fr.atoms[i];
        fprintf(fp, "%5d%-5.5s%5.5s%5d", a.resnr % 100000, a.resname.c_str(), a.atomname.c_str(), a.atomnr % 100000);
        for (int d = 0; d < 3; ++d) fprintf(fp, xfmt.c_str(), a.x[d]);
        if (writeVelocities) {
            for (int d = 0; d < 3; ++d) fprintf(fp, vfmt.c_str(), a.v[d]);
        }
        fputc('\n', fp);
    }
    bool triclinic = fr.box[0][1] != 0 || fr.box[0][2] != 0 || fr.box[1][0] != 0 || fr.box[1][2] != 0 || fr.box[2][0] != 0 || fr.box[2][1] != 0;
    if (!triclinic) {
        fprintf(fp, "%10.5f%10.5f%10.5f\n", fr.box[0][0], fr.box[1][1], fr.box[2][2]);
    } else {
        fprintf(fp, "%10.5f%10.5f%10.5f%10.5f%10.5f%10.5f%10.5f%10.5f%10.5f\n",
                fr.box[0][0], fr.box[1][1], fr.box[2][2],
                fr.box[0][1], fr.box[0][2], fr.box[1][0], fr.box[1][2], fr.box[2][0], fr.box[2][1]);
    }
}

void writePdb(FILE* fp, const Frame& fr)
{
    fprintf(fp, "TITLE     %s\n", fr.title.c_str());
    fprintf(fp, "REMARK    THIS IS A SIMULATION BOX\n");
    if (fr.hasBox) {
        double a = sqrt(fr.box[0][0] * fr.box[0][0] + fr.box[0][1] * fr.box[0][1] + fr.box[0][2] * fr.box[0][2]) * 10;
        double b = sqrt(fr.box[1][0] * fr.box[1][0] + fr.box[1][1] * fr.box[1][1] + fr.box[1][2] * fr.box[1][2]) * 10;
        double c = sqrt(fr.box[2][0] * fr.box[2][0] + fr.box[2][1] * fr.box[2][1] + fr.box[2][2] * fr.box[2][2]) * 10;
        double alpha = 90, beta = 90, gamma = 90;
        if (b > 0 && c > 0) alpha = acos((fr.box[1][0] * fr.box[2][0] + fr.box[1][1] * fr.box[2][1] + fr.box[1][2] * fr.box[2][2]) * 100 / (b * c)) * 180 / M_PI;
        if (a > 0 && c > 0) beta = acos((fr.box[0][0] * fr.box[2][0] + fr.box[0][1] * fr.box[2][1] + fr.box[0][2] * fr.box[2][2]) * 100 / (a * c)) * 180 / M_PI;
        if (a > 0 && b > 0) gamma = acos((fr.box[0][0] * fr.box[1][0] + fr.box[0][1] * fr.box[1][1] + fr.box[0][2] * fr.box[1][2]) * 100 / (a * b)) * 180 / M_PI;
        fprintf(fp, "CRYST1%9.3f%9.3f%9.3f%7.2f%7.2f%7.2f P 1           1\n", a, b, c, alpha, beta, gamma);
    }
    fprintf(fp, "MODEL %8d\n", 1);
    for (size_t i = 0; i < fr.atoms.size(); ++i) {
        const Atom& a = fr.atoms[i];
        std::string nm = a.atomname;
        std::string nmField;
        if (nm.size() < 4 && !(nm.size() > 0 && isdigit((unsigned char)nm[0]))) nmField = " " + nm; else nmField = nm;
        fprintf(fp, "%-6s%5d %-4.4s%c%-4.4s%c%4d%c   %8.3f%8.3f%8.3f%6.2f%6.2f          %2s%2s\n",
                a.pdbRecord.c_str(), (a.atomnr) % 100000, nmField.c_str(), a.altloc, a.resname.c_str(), a.chain,
                a.resnr % 10000, ' ', a.x[0] * 10, a.x[1] * 10, a.x[2] * 10, a.occupancy, a.bfactor,
                a.element.c_str(), "");
    }
    fprintf(fp, "TER\n");
    fprintf(fp, "ENDMDL\n");
}

void writeStructure(const std::string& fileName, const Frame& fr, bool writeVelocities)
{
    FILE* fp = openOutputFile(fileName);
    std::string type = fileTypeName(fileName);
    if (type == "pdb" || type == "brk" || type == "ent") writePdb(fp, fr);
    else writeGro(fp, fr, writeVelocities, fr.precisionDecimals);
    fclose(fp);
}

} // namespace gmx
