// gmx genconf: multiply a conformation in a grid.
#include "gmx.h"
#include "structure.h"
#include <cmath>
#include <random>

namespace gmx {

static void rotateCoords(double x[3], const double angles[3])
{
    // rotate around X, Y, Z axes successively (angles in radians)
    double r[3] = {x[0], x[1], x[2]};
    // X
    double c = cos(angles[0]), s = sin(angles[0]);
    double y1 = c * r[1] - s * r[2];
    double z1 = s * r[1] + c * r[2];
    r[1] = y1; r[2] = z1;
    // Y
    c = cos(angles[1]); s = sin(angles[1]);
    double x2 = c * r[0] + s * r[2];
    double z2 = -s * r[0] + c * r[2];
    r[0] = x2; r[2] = z2;
    // Z
    c = cos(angles[2]); s = sin(angles[2]);
    double x3 = c * r[0] - s * r[1];
    double y3 = s * r[0] + c * r[1];
    r[0] = x3; r[1] = y3;
    x[0] = r[0]; x[1] = r[1]; x[2] = r[2];
}

int runGenconf(const gmxdata::ModuleDef& mod, const std::vector<std::string>& args)
{
    ParsedOptions po = parseModuleOptions(mod, args);
    std::string inFile = po.file("f");
    std::string outFile = po.file("o");
    double nboxv[3], dist[3], maxrot[3];
    po.vector("nbox", nboxv);
    po.vector("dist", dist);
    po.vector("maxrot", maxrot);
    bool bRot = po.boolean("rot");
    bool bRenum = po.boolean("renumber");
    int seed = po.integer("seed");

    Frame fr;
    std::string err;
    if (!readStructure(inFile, fr, &err)) {
        throw fatalError(formatString("Could not read structure file %s", inFile.c_str()), "src/gromacs/gmxpreprocess/genconf.cpp", 200);
    }
    int nx = (int)nboxv[0], ny = (int)nboxv[1], nz = (int)nboxv[2];
    if (nx <= 0 || ny <= 0 || nz <= 0) {
        throw fatalError("Number of boxes (-nbox) should be larger than zero", "src/gromacs/gmxpreprocess/genconf.cpp", 180);
    }
    int natoms = (int)fr.atoms.size();
    int nres = 0;
    for (const Atom& a : fr.atoms) if (a.resnr > nres) nres = a.resnr;
    // count residues as distinct consecutive residue numbers
    {
        int count = 0;
        int last = -1;
        for (const Atom& a : fr.atoms) {
            if (a.resnr != last) { ++count; last = a.resnr; }
        }
        nres = count;
    }

    std::mt19937 rng(seed == 0 ? (unsigned)time(nullptr) : (unsigned)seed);
    std::uniform_real_distribution<double> uni(0.0, 1.0);

    Frame out;
    out.title = fr.title;
    out.hasVelocities = fr.hasVelocities;
    out.hasBox = fr.hasBox;
    out.precisionDecimals = fr.precisionDecimals;
    out.atoms.reserve((size_t)natoms * nx * ny * nz);

    // compute center for rotation
    double center[3] = {0, 0, 0};
    for (const Atom& a : fr.atoms) for (int d = 0; d < 3; ++d) center[d] += a.x[d];
    if (natoms > 0) for (int d = 0; d < 3; ++d) center[d] /= natoms;

    int copy = 0;
    for (int k = 0; k < nz; ++k) {
        for (int j = 0; j < ny; ++j) {
            for (int i = 0; i < nx; ++i) {
                double shift[3];
                for (int d = 0; d < 3; ++d) {
                    shift[d] = i * fr.box[0][d] + j * fr.box[1][d] + k * fr.box[2][d];
                }
                shift[0] += i * dist[0];
                shift[1] += j * dist[1];
                shift[2] += k * dist[2];
                double ang[3] = {0, 0, 0};
                if (bRot) {
                    for (int d = 0; d < 3; ++d) ang[d] = (2 * uni(rng) - 1) * maxrot[d] * M_PI / 180.0;
                }
                for (int ai = 0; ai < natoms; ++ai) {
                    Atom a = fr.atoms[ai];
                    if (bRot) {
                        double r[3] = {a.x[0] - center[0], a.x[1] - center[1], a.x[2] - center[2]};
                        rotateCoords(r, ang);
                        for (int d = 0; d < 3; ++d) a.x[d] = r[d] + center[d];
                        rotateCoords(a.v, ang);
                    }
                    for (int d = 0; d < 3; ++d) a.x[d] += shift[d];
                    a.atomnr = (int)out.atoms.size() + 1;
                    if (bRenum) a.resnr = fr.atoms[ai].resnr + copy * nres;
                    out.atoms.push_back(a);
                }
                ++copy;
            }
        }
    }
    double nb[3] = {(double)nx, (double)ny, (double)nz};
    for (int d = 0; d < 3; ++d) {
        for (int e = 0; e < 3; ++e) out.box[d][e] = fr.box[d][e] * nb[d];
        out.box[d][d] += nb[d] * dist[d];
    }
    writeStructure(outFile, out, out.hasVelocities);
    return 0;
}

} // namespace gmx
