        for (const Atom& a : fr.atoms) {
            if (a.resnr != last) { ++count; last = a.resnr; }
        }
        nres = count;
    }

    std::mt19937 rng(seed == 0 ? (unsigned)time(nullptr) : (unsigned)seed);
    std::uniform_real_distribution<double> uni(0.0, 1.0);

    Frame out;
    out.title = fr.title;
    out.hasVelocities = fr.hasVelocities;
    out.hasBox = fr.hasBox;
    out.precisionDecimals = fr.precisionDecimals;
    out.atoms.reserve((size_t)natoms * nx * ny * nz);

    // compute center for rotation
    double center[3] = {0, 0, 0};
    for (const Atom& a : fr.atoms) for (int d = 0; d < 3; ++d) center[d] += a.x[d];
    if (natoms > 0) for (int d = 0; d < 3; ++d) center[d] /= natoms;

    int copy = 0;
    for (int k = 0; k < nz; ++k) {
        for (int j = 0; j < ny; ++j) {
            for (int i = 0; i < nx; ++i) {
                double shift[3];
                for (int d = 0; d < 3; ++d) {
                    shift[d] = i * fr.box[0][d] + j * fr.box[1][d] + k * fr.box[2][d];
                }
                shift[0] += i * dist[0];
                shift[1] += j * dist[1];
                shift[2] += k * dist[2];
                double ang[3] = {0, 0, 0};
                if (bRot) {
                    for (int d = 0; d < 3; ++d) ang[d] = (2 * uni(rng) - 1) * maxrot[d] * M_PI / 180.0;
                }
                for (int ai = 0; ai < natoms; ++ai) {
                    Atom a = fr.atoms[ai];
                    if (bRot) {
                        double r[3] = {a.x[0] - center[0], a.x[1] - center[1], a.x[2] - center[2]};
                        rotateCoords(r, ang);
                        for (int d = 0; d < 3; ++d) a.x[d] = r[d] + center[d];
                        rotateCoords(a.v, ang);
                    }
                    for (int d = 0; d < 3; ++d) a.x[d] += shift[d];
                    a.atomnr = (int)out.atoms.size() + 1;
                    if (bRenum) a.resnr = fr.atoms[ai].resnr + copy * nres;
                    out.atoms.push_back(a);
                }
                ++copy;
            }
        }
    }
    double nb[3] = {(double)nx, (double)ny, (double)nz};
    for (int d = 0; d < 3; ++d) {
        for (int e = 0; e < 3; ++e) out.box[d][e] = fr.box[d][e] * nb[d];
        out.box[d][d] += nb[d] * dist[d];
    }
    writeStructure(outFile, out, out.hasVelocities);
    return 0;
}

