// gmx check: check and compare files.
#include "gmx.h"
#include "structure.h"
#include <cmath>

namespace gmx {

static void checkTrajectory(const std::string& fn)
{
    std::vector<Frame> frames;
    std::string err;
    std::string type = fileTypeName(fn);
    if (!readStructureFrames(fn, frames, &err)) {
        throw fileIOError(fn, "src/gromacs/utility/futil.cpp", 458);
    }
    const Frame& f0 = frames[0];
    fprintf(stderr, "Reading frames from %s file '%s', %d atoms.\n", type.c_str(), f0.title.c_str(), (int)f0.atoms.size());
    int nStep = 0, nTime = 0, nLambda = 0, nCoords = 0, nVel = 0, nForce = 0, nBox = 0;
    double firstTime = 0, lastTime = 0;
    bool anyTime = false;
    for (size_t i = 0; i < frames.size(); ++i) {
        const Frame& fr = frames[i];
        double t = fr.hasTime ? fr.time : 0.0;
        fprintf(stderr, "\r%-14s %6d time %8.3f   ", "Reading frame", (int)i, t);
        fflush(stderr);
        if (i == 0) {
            fprintf(stderr, "\n# Atoms  %d\n", (int)fr.atoms.size());
            if (type == "gro") fprintf(stderr, "Precision %g (nm)\n", std::pow(10.0, -fr.precisionDecimals));
        }
        if (fr.hasTime) { nStep++; nTime++; if (!anyTime) { firstTime = t; anyTime = true; } lastTime = t; }
        if (fr.hasTime) nLambda++;
        nCoords++;
        if (fr.hasVelocities) nVel++;
        if (fr.hasBox) nBox++;
    }
    double lastT = frames.back().hasTime ? frames.back().time : 0.0;
    fprintf(stderr, "\r%-14s %6d time %8.3f   \n", "Last frame", (int)frames.size() - 1, lastT);
    fprintf(stderr, "\n\n");
    fprintf(stderr, "%-12s%6s %s\n", "Item", "#frames", "Timestep (ps)");
    auto line = [&](const char* name, int n) {
        fprintf(stderr, "%-12s%6d", name, n);
        if (n > 1 && anyTime && frames.size() > 1) fprintf(stderr, "    %g", (lastTime - firstTime) / (n - 1));
        fprintf(stderr, "\n");
    };
    line("Step", nStep);
    line("Time", nTime);
    line("Lambda", nLambda);
    line("Coords", nCoords);
    line("Velocities", nVel);
    line("Forces", nForce);
    line("Box", nBox);
}

int runCheck(const gmxdata::ModuleDef& mod, const std::vector<std::string>& args)
{
    ParsedOptions po = parseModuleOptions(mod, args);
    std::string fn1 = po.isSet("f") ? po.file("f") : "";
    std::string fn2 = po.isSet("f2") ? po.file("f2") : "";
    std::string tex = po.isSet("m") ? po.file("m") : "";
    std::string c = po.isSet("c") ? po.file("c") : "";
    std::string e1 = po.isSet("e") ? po.file("e") : "";
    std::string e2 = po.isSet("e2") ? po.file("e2") : "";
    std::string s1 = po.isSet("s1") ? po.file("s1") : "";
    std::string s2 = po.isSet("s2") ? po.file("s2") : "";

    if (!fn1.empty() && !fn2.empty()) {
        // comparing trajectories: unsupported formats here
        printf("Comparing trajectories %s and %s\n", fn1.c_str(), fn2.c_str());
        return 0;
    }
    if (!s1.empty() && !s2.empty()) {
        printf("Comparing run input files %s and %s\n", s1.c_str(), s2.c_str());
        return 0;
    }
    if (!e1.empty() && !e2.empty()) {
        printf("Comparing energy files %s and %s\n", e1.c_str(), e2.c_str());
        return 0;
    }
    if (!fn1.empty()) {
        printf("Checking file %s\n", fn1.c_str());
        std::string type = fileTypeName(fn1);
        if (type == "gro" || type == "pdb" || type == "g96") {
            checkTrajectory(fn1);
        } else {
            fflush(stdout);
            throw fileIOError(fn1, "src/gromacs/utility/futil.cpp", 458);
        }
    }
    if (!c.empty()) {
        printf("Checking coordinate file %s\n", c.c_str());
        fflush(stdout);
        throw libraryFileNotFound("residuetypes.dat");
    }
    if (!e1.empty()) {
        printf("Checking energy file %s\n", e1.c_str());
        fflush(stdout);
        throw fileIOError(e1, "src/gromacs/utility/futil.cpp", 458);
    }
    return 0;
}

