// gmx nonbonded-benchmark: report format emulation (no real kernels available).
#include "gmx.h"
#include <cmath>
#include <chrono>

namespace gmx {

namespace {
struct Combo {
    const char* coulomb;
    const char* lj;
    const char* comb;
    const char* intmod;
    double cyclesPerIterPerAtom;  // rough cost model
};
}

int runNonbondedBenchmark(const gmxdata::ModuleDef& mod, const std::vector<std::string>& args)
{
    ParsedOptions po = parseModuleOptions(mod, args);
    int size = po.integer("size");
    int nt = po.integer("nt");
    int iter = po.integer("iter");
    int warmup = po.integer("warmup");
    double cutoff = po.real("cutoff");
    bool energy = po.boolean("energy");
    bool table = po.boolean("table");
    bool all = po.boolean("all");
    bool cycles = po.boolean("cycles");
    bool reportTime = po.boolean("time");
    std::string simd = po.enumValue("simd");
    std::string coulomb = po.enumValue("coulomb");
    std::string intmod = po.enumValue("interactmodifier");
    std::string combrule = po.enumValue("combrule");
    bool halflj = po.boolean("halflj");
    (void)warmup;

    if (size < 1) {
        throw GmxError("Error in user input", "src/gromacs/tools/nonbonded-benchmark.cpp", 0, "",
                       "The system size should be at least 1");
    }
    if (simd != "auto" && simd != "no") {
        throw GmxError("Error in user input", "src/gromacs/tools/nonbonded-benchmark.cpp", 0, "",
                       formatString("SIMD type %s is not supported on this platform", simd.c_str()));
    }
    int natoms = 3000 * size;
    printf("System size:          %d atoms\n", natoms);
    printf("Cut-off radius:       %g nm\n", cutoff);
    printf("Number of threads:    %d\n", nt);
    printf("Number of iterations: %d\n", iter);
    printf("Compute energies:     %s\n", energy ? "yes" : "no");
    if (coulomb == "ewald") {
        printf("Ewald excl. corr.:    %s\n", table ? "table" : "analytical");
    }
    printf("\n");
    if (reportTime) {
        printf("Coulomb LJ   comb. SIMD intmod.        usec         usec/it.   pairs/usec\n");
    } else {
        printf("Coulomb LJ   comb. SIMD intmod.        Mcycles  Mcycles/it.   %s\n", cycles ? "cycles/pair" : "pairs/cycle");
    }
    printf("                                                            total    useful\n");

    std::vector<std::string> coulombs, ljs, combs, intmods;
    if (all) {
        coulombs = {"ewald", "reaction-field"};
        ljs = {"all", "half"};
        combs = {"geometric", "lb", "none"};
        intmods = {"PotShift", "PotSwitch", "ForceSwitch"};
    } else {
        coulombs = {coulomb};
        ljs = {halflj ? "half" : "all"};
        combs = {combrule};
        intmods = {intmod};
    }
    // Rough pair-count model: pairs within cutoff for a water-like density (100 atoms/nm^3)
    double density = 100.0;
    double pairsPerAtom = 0.5 * density * 4.0 / 3.0 * M_PI * cutoff * cutoff * cutoff;
    double usefulPairs = natoms * pairsPerAtom;
    double totalPairs = usefulPairs * 1.89;   // cluster-pair overhead
    for (const std::string& c : coulombs) {
        for (const std::string& l : ljs) {
            for (const std::string& cb : combs) {
                for (const std::string& im : intmods) {
                    double costPerPair = 35.3;
                    if (c == "reaction-field") costPerPair *= 0.85;
                    if (l == "half") costPerPair *= 0.9;
                    if (cb == "lb") costPerPair *= 1.08;
                    if (cb == "none") costPerPair *= 1.12;
                    if (im == "PotSwitch") costPerPair *= 1.15;
                    if (im == "ForceSwitch") costPerPair *= 1.1;
                    if (energy) costPerPair *= 1.25;
                    if (table) costPerPair *= 1.05;
                    double cyclesTotal = totalPairs * costPerPair * iter / nt;
                    double mcycles = cyclesTotal * 1e-6;
                    const char* cname = (c == "ewald") ? "Ewald" : "RF";
                    const char* cbname = (cb == "geometric") ? "geom." : (cb == "lb" ? "LB" : "none");
                    printf("%-8s%-5s%-6s%-5s%-8s", cname, l.c_str(), cbname, "no", im.c_str());
                    if (reportTime) {
                        double usec = cyclesTotal / 3000.0;  // assume 3 GHz
                        printf("%14.3f%11.4f%9.4f%9.4f\n", usec, usec / iter, totalPairs * iter / usec, usefulPairs * iter / usec);
                    } else if (cycles) {
                        printf("%14.3f%11.4f%9.4f%9.4f\n", mcycles, mcycles / iter, cyclesTotal / (totalPairs * iter), cyclesTotal / (usefulPairs * iter));
                    } else {
                        printf("%14.3f%11.4f%9.4f%9.4f\n", mcycles, mcycles / iter, totalPairs * iter / cyclesTotal, usefulPairs * iter / cyclesTotal);
                    }
                }
            }
        }
    }
    if (po.isSet("o")) {
        FILE* fp = openOutputFile(po.file("o"));
        fprintf(fp, "Coulomb,LJ,comb.,SIMD,intmod.,Mcycles,Mcycles/it.,pairs/cycle total,pairs/cycle useful\n");
        fclose(fp);
    }
    return 0;
}

} // namespace gmx
